// mod2.js - array helper utilities
// Small, dependency-free helpers for working with arrays.

/**
 * Split an array into chunks of a given size.
 * @param {Array} arr
 * @param {number} size
 * @returns {Array<Array>}
 */
function chunk(arr, size) {
  const result = [];
  if (size <= 0) {
    return result;
  }
  for (let i = 0; i < arr.length; i += size) {
    result.push(arr.slice(i, i + size));
  }
  return result;
}

/**
 * Return a new array with duplicate values removed.
 * @param {Array} arr
 * @returns {Array}
 */
function unique(arr) {
  return Array.from(new Set(arr));
}

/**
 * Flatten a nested array by one level.
 * @param {Array} arr
 * @returns {Array}
 */
function flattenOnce(arr) {
  return arr.reduce((acc, item) => acc.concat(item), []);
}

module.exports = { chunk, unique, flattenOnce };

