// Shallow helpers for picking, omitting and merging plain objects.

/**
 * Create a new object containing only the listed keys.
 * @param {Object} obj
 * @param {string[]} keys
 * @returns {Object}
 */
function pick(obj, keys) {
  const out = {};
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      out[key] = obj[key];
    }
  }
  return out;
}

/**
 * Create a new object without the listed keys.
 * @param {Object} obj
 * @param {string[]} keys
 * @returns {Object}
 */
function omit(obj, keys) {
  const drop = new Set(keys);
  const out = {};
  for (const key of Object.keys(obj)) {
    if (!drop.has(key)) {
      out[key] = obj[key];
    }
  }
  return out;
}

