// mod6.js - function utilities
// Higher-order helpers for controlling how functions are called.

/**
 * Wrap a function so it only runs once; later calls return the first result.
 * @param {Function} fn
 * @returns {Function}
 */
function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

/**
 * Return a function that calls fn with arguments reversed.
 * @param {Function} fn
 * @returns {Function}
 */
function flip(fn) {
  return function (...args) {
    return fn.apply(this, args.reverse());
  };
}

/**
 * Partially apply leading arguments to a function.
 * @param {Function} fn
 * @param {...*} preset
 * @returns {Function}
 */
function partial(fn, ...preset) {
  return function (...rest) {
    return fn.apply(this, preset.concat(rest));
  };
}

module.exports = { once, flip, partial };

