// mod8.js - timing utilities
// Helpers for measuring and scheduling work.

/**
 * Pause execution for a number of milliseconds.
 * @param {number} ms
 * @returns {Promise<void>}
 */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Measure how long a synchronous function takes to run.
 * @param {Function} fn
 * @returns {{result: *, elapsedMs: number}}
 */
function measure(fn) {
  const start = Date.now();
  const result = fn();
  return { result, elapsedMs: Date.now() - start };
}

/**
 * Retry an async function a fixed number of times before giving up.
 * @param {Function} fn - returns a Promise
 * @param {number} attempts
 * @returns {Promise<*>}
 */
async function retry(fn, attempts) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

module.exports = { sleep, measure, retry };

