function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Measure how long a synchronous function takes to run.
 * @param {Function} fn
 * @returns {{result: *, elapsedMs: number}}
 */
function measure(fn) {
  const start = Date.now();
  const result = fn();
  return { result, elapsedMs: Date.now() - start };
}

