 * @param {Function} fn - returns a Promise
 * @param {number} attempts
 * @returns {Promise<*>}
 */
async function retry(fn, attempts) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

module.exports = { sleep, measure, retry };

